<script setup lang="ts">import type{Diagnostic}from '../types/domain';import{dimensionLabels}from '../constants/enums';import{number,percent}from '../utils/format';defineProps<{items:Diagnostic[]}>();</script><template><div class="table-wrap"><table><thead><tr><th>维度 / 类别</th><th>原始占比</th><th>目标占比</th><th>加权占比</th><th>目标总数</th><th>权重总数</th><th>绝对残差</th></tr></thead><tbody><tr v-for="d in items" :key="d.dimension+d.category"><td><small>{{dimensionLabels[d.dimension]}}</small><strong>{{d.category}}</strong></td><td>{{percent(d.unweighted_share)}}</td><td>{{percent(d.target_share)}}</td><td>{{percent(d.weighted_share)}}</td><td>{{number(d.target)}}</td><td>{{number(d.weighted)}}</td><td>{{number(d.residual,3)}}</td></tr></tbody></table></div></template>
